def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_competitors = len(alive_opponents)

    # Initial bid consideration based on general value and moderate competition
    bid_target = DAILY_SALARY * 0.5 

    # HP-based adjustment: The lower the HP, the higher the bid
    if my_hp <= 2: 
        bid_target = DAILY_SALARY * 0.95 
    elif my_hp <= 4: 
        bid_target = DAILY_SALARY * 0.8 
    elif my_hp <= 6: 
        bid_target = DAILY_SALARY * 0.65 
    else: 
        bid_target = DAILY_SALARY * 0.5 

    # Day-based adjustment: Increase bid towards the end of the episode
    days_remaining = EPISODE_DAYS - current_day
    if days_remaining <= 2:
        bid_target *= 1.15 
    elif days_remaining <= 4:
        bid_target *= 1.05 

    # Supply-based adjustment: Increase bid if supply is tight
    num_possible_winners = int(current_supply // WATER_REQ)
    total_potential_demanders = num_alive_competitors + 1

    if num_possible_winners < total_potential_demanders:
        if num_possible_winners == 0: 
             bid_target *= 1.4 
        elif num_possible_winners == 1 and total_potential_demanders > 1: 
            bid_target *= 1.25 
        else: 
            bid_target *= 1.1 
    else:
        bid_target *= 0.9 

    # Opponent-based adjustment (using previous_trace)
    highest_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

    if highest_prev_bid > 0: 
        if my_hp <= 4 or num_possible_winners < total_potential_demanders:
            if highest_prev_bid < DAILY_SALARY * 0.9: 
                bid_target = max(bid_target, highest_prev_bid + 2.0) 
            else: 
                bid_target = max(bid_target, highest_prev_bid + 1.0)
        else:
            if highest_prev_bid < DAILY_SALARY * 0.5:
                bid_target = max(bid_target, highest_prev_bid + 1.0)

    # Final bid must be within budget and at least 1
    final_bid = min(my_budget, bid_target)
    final_bid = max(1.0, final_bid)

    return final_bid

